import time, functools

def timed(fn):
    @functools.wraps(fn)
    def wrapper(*a, **kw):
        t = time.perf_counter()
        try:
            return fn(*a, **kw)
        finally:
            print(f"{fn.__name__}: {time.perf_counter() - t:.4f}s")
    return wrapper

@timed
def work():
    sum(range(10**7))
